describe('File Upload Functionality', () => {
    beforeEach(() => {
        cy.visit('/upload'); // Replace with the actual URL of the upload page
    });

    it('should upload multiple files successfully', () => {
        const filesToUpload = [
            'file1.txt',
            'file2.jpg',
            'file3.pdf'
        ];

        const fileInput = cy.get('input[type="file"]'); // Adjust selector as needed

        fileInput.attachFile(filesToUpload);

        cy.get('button[type="submit"]').click(); // Adjust selector as needed

        cy.get('.upload-success-message').should('be.visible'); // Adjust selector as needed
        cy.get('.uploaded-files-list').should('contain', 'file1.txt');
        cy.get('.uploaded-files-list').should('contain', 'file2.jpg');
        cy.get('.uploaded-files-list').should('contain', 'file3.pdf');
    });

    it('should show an error when no files are selected', () => {
        cy.get('button[type="submit"]').click(); // Adjust selector as needed

        cy.get('.error-message').should('be.visible'); // Adjust selector as needed
        cy.get('.error-message').should('contain', 'Please select at least one file to upload.'); // Adjust message as needed
    });
});
